<script setup lang="ts">
import { computed, ref } from 'vue';
import Icon from '../components/Icon.vue';
import { data, mutate, busy, avatarStyle, dateLabel, navigate } from '../store';
const filter = ref('全部');
const selectedId = ref('');
const flows = computed(()=>data.lifecycles.filter(l=>filter.value==='全部'||l.type===filter.value));
const selected = computed(()=>flows.value.find(f=>f.id===selectedId.value)||flows.value[0]);
const done = computed(()=>selected.value?.checklist.filter(c=>c.done).length || 0);
const percent = computed(()=>Math.round(done.value/(selected.value?.checklist.length||1)*100));
const employee = computed(()=>data.employees.find(e=>e.id===selected.value?.employeeId));
async function check(id:string, checked:boolean) { if(selected.value)await mutate(`/lifecycles/${selected.value.id}/checklist/${id}`,{done:checked},'PATCH','办理清单已更新'); }
async function complete() { if(selected.value)await mutate(`/lifecycles/${selected.value.id}/complete`,{},'POST','流程已办结，员工状态已同步'); }
</script>
<template><div class="page-heading"><div><span class="eyebrow">EMPLOYEE JOURNEY</span><h1>入转调离</h1><p class="page-subtitle">把每一个重要节点，变成有温度的员工体验。</p></div><button class="btn" @click="navigate('recruitment')"><Icon name="userPlus" :size="18"/>从招聘发起入职</button></div><div class="journey-stats"><button v-for="(type,i) in ['入职','转正','调岗','离职']" :key="type" class="panel journey-stat" :class="{selected:filter===type}" @click="filter=filter===type?'全部':type"><span class="quick-icon" :class="['blue','teal','violet','amber'][i]"><Icon :name="['userPlus','shield','transfer','logout'][i]" :size="23"/></span><div><span>待办理{{ type }}</span><strong>{{ data.lifecycles.filter(l=>l.type===type&&l.status==='进行中').length }}<small>人</small></strong></div><Icon name="arrowUpRight" :size="18"/></button></div><section class="panel journey-layout"><aside class="journey-list"><div class="panel-header"><h2>流程列表</h2><button class="text-button" @click="filter='全部'">全部</button></div><button v-for="flow in flows" :key="flow.id" class="journey-person" :class="{active:selected?.id===flow.id}" @click="selectedId=flow.id"><span class="avatar" :style="avatarStyle(flow.name)">{{ flow.name.slice(-1) }}</span><span class="journey-person-info"><strong>{{ flow.name }}<span class="badge" :class="flow.status==='已完成'?'badge-green':'badge-blue'">{{ flow.type }}</span></strong><small>{{ flow.department }} · {{ dateLabel(flow.effectiveDate) }}</small><span class="progress-track"><i class="progress-fill" :style="{width:flow.checklist.filter(c=>c.done).length/(flow.checklist.length||1)*100+'%'}"></i></span></span><Icon name="chevronRight" :size="15"/></button><div v-if="!flows.length" class="empty-state"><p>暂无此类流程</p></div></aside><div v-if="selected" class="journey-detail"><div class="journey-detail-heading"><div class="person-cell"><span class="avatar large" :style="avatarStyle(selected.name)">{{ selected.name.slice(-1) }}</span><div><h2>{{ selected.name }}的{{ selected.type }}旅程</h2><p>{{ employee?.position }} · {{ selected.department }}</p></div></div><span class="badge" :class="selected.status==='已完成'?'badge-green':'badge-blue'">{{ selected.status }}</span></div><div class="journey-meta"><div><small>预计生效日期</small><strong>{{ selected.effectiveDate }}</strong></div><div><small>流程负责人</small><strong>{{ selected.owner }}</strong></div><div><small>当前员工状态</small><strong>{{ employee?.status || '待关联' }}</strong></div></div><div class="checklist-heading"><h3>协同办理清单</h3><span>已完成 {{ done }} / {{ selected.checklist.length }} 项</span></div><div class="progress-track journey-progress"><div class="progress-fill" :style="{width:percent+'%'}"></div></div><label v-for="(item,i) in selected.checklist" :key="item.id" class="checklist-item" :class="{done:item.done}"><input type="checkbox" :checked="item.done" :disabled="busy||selected.status==='已完成'" @change="check(item.id,($event.target as HTMLInputElement).checked)"/><span><strong>{{ item.label }}</strong><small>步骤 {{ (i+1).toString().padStart(2,'0') }} · {{ item.done?'已完成':'等待协同处理' }}</small></span><span v-if="item.done" class="checklist-status">已就绪<Icon name="checkCircle" :size="18"/></span></label><div class="journey-bottom"><span><Icon name="shield" :size="17"/>每次变更均保留操作记录</span><button class="btn btn-primary" :disabled="busy||percent<100||selected.status==='已完成'" @click="complete"><Icon name="check" :size="17"/>{{ selected.status==='已完成'?'流程已办结':'确认办结' }}</button></div><p v-if="selected.status!=='已完成'" class="data-note">完成全部清单后可办结；入职和转正将同步为正式员工，离职将同步为已离职。</p></div><div v-else class="empty-state"><Icon name="path" :size="36"/><p>当前没有待办理流程</p></div></section></template>
